    """Merge overlapping or touching closed intervals.

    The input sequence is never mutated and the returned list contains fresh
    ``[start, end]`` lists, so callers may modify the result freely.
    """
    ordered = sorted((item[0], item[1]) for item in intervals)
    result = []
    for start, end in ordered:
        if result and overlaps(result[-1], (start, end)):
            if end > result[-1][1]:
                result[-1][1] = end
        else:
            result.append([start, end])
    return result"}
